    74	// convertAppProberHTTPGet returns an overwritten `Probe` (HttpGet) for pilot agent to take over.
    75	func convertAppProberHTTPGet(probe *corev1.Probe, newURL string, statusPort int) *corev1.Probe {
    76		p := probe.DeepCopy()
    77		// Change the application container prober config.
    78		p.HTTPGet.Port = intstr.FromInt(statusPort)
    79		p.HTTPGet.Path = newURL
    80		// For HTTPS prober, we change to HTTP,
    81		// and pilot agent uses https to request application prober endpoint.
    82		// Kubelet -> HTTP -> Pilot Agent -> HTTPS -> Application
    83		if p.HTTPGet.Scheme == corev1.URISchemeHTTPS {
    84			p.HTTPGet.Scheme = corev1.URISchemeHTTP
    85		}
    86		return p
    87	}
