    90	func convertAppProberTCPSocket(probe *corev1.Probe, newURL string, statusPort int) *corev1.Probe {
    91		p := probe.DeepCopy()
    92		// the sidecar intercepts all tcp connections, so we change it to a HTTP probe and the sidecar will check tcp
    93		p.HTTPGet = &corev1.HTTPGetAction{}
    94		p.HTTPGet.Port = intstr.FromInt(statusPort)
    95		p.HTTPGet.Path = newURL
    96	
    97		p.TCPSocket = nil
    98		return p
