   110	// DumpAppProbers returns a json encoded string as `status.KubeAppProbers`.
   111	// Also update the probers so that all usages of named port will be resolved to integer.
   112	func DumpAppProbers(podspec *corev1.PodSpec, targetPort int32) string {
   113		out := KubeAppProbers{}
   114		updateNamedPort := func(p *Prober, portMap map[string]int32) *Prober {
   115			if p == nil || (p.HTTPGet == nil && p.TCPSocket == nil) {
   116				return nil
   117			}
   118	
   119			var probePort *intstr.IntOrString
   120			if p.HTTPGet != nil {
   121				probePort = &p.HTTPGet.Port
   122			} else {
   123				probePort = &p.TCPSocket.Port
   124			}
   125	
   126			if probePort.Type == intstr.String {
   127				port, exists := portMap[probePort.StrVal]
   128				if !exists {
   129					return nil
   130				}
   131				*probePort = intstr.FromInt(int(port))
   132			} else if probePort.IntVal == targetPort {
   133				// Already is rewritten
   134				return nil
   135			}
   136			return p
   137		}
   138		for _, c := range podspec.Containers {
   139			if c.Name == ProxyContainerName {
   140				continue
   141			}
   142			readyz, livez, startupz := status.FormatProberURL(c.Name)
   143			portMap := map[string]int32{}
   144			for _, p := range c.Ports {
   145				if p.Name != "" {
   146					portMap[p.Name] = p.ContainerPort
   147				}
   148			}
   149			if h := updateNamedPort(kubeProbeToInternalProber(c.ReadinessProbe), portMap); h != nil {
   150				out[readyz] = h
   151			}
   152			if h := updateNamedPort(kubeProbeToInternalProber(c.LivenessProbe), portMap); h != nil {
   153				out[livez] = h
   154			}
   155			if h := updateNamedPort(kubeProbeToInternalProber(c.StartupProbe), portMap); h != nil {
   156				out[startupz] = h
   157			}
   158	
   159		}
   160		// prevent generate '{}'
   161		if len(out) == 0 {
   162			return ""
   163		}
   164		b, err := json.Marshal(out)
   165		if err != nil {
   166			log.Errorf("failed to serialize the app prober config %v", err)
   167			return ""
   168		}
   169		return string(b)
   170	}
