   172	// patchRewriteProbe generates the patch for webhook.
   173	func patchRewriteProbe(annotations map[string]string, pod *corev1.Pod, defaultPort int32) {
   174		sidecar := FindSidecar(pod.Spec.Containers)
   175		if sidecar == nil {
   176			return
   177		}
   178		statusPort := int(defaultPort)
   179		if v, f := annotations[annotation.SidecarStatusPort.Name]; f {
   180			p, err := strconv.Atoi(v)
   181			if err != nil {
   182				log.Errorf("Invalid annotation %v=%v: %v", annotation.SidecarStatusPort.Name, v, err)
   183			}
   184			statusPort = p
   185		}
   186		for i, c := range pod.Spec.Containers {
   187			// Skip sidecar container.
   188			if c.Name == ProxyContainerName {
   189				continue
   190			}
   191			portMap := map[string]int32{}
   192			for _, p := range c.Ports {
   193				portMap[p.Name] = p.ContainerPort
   194			}
   195			readyz, livez, startupz := status.FormatProberURL(c.Name)
   196			if probePatch := convertAppProber(c.ReadinessProbe, readyz, statusPort); probePatch != nil {
   197				c.ReadinessProbe = probePatch
   198			}
   199			if probePatch := convertAppProber(c.LivenessProbe, livez, statusPort); probePatch != nil {
   200				c.LivenessProbe = probePatch
   201			}
   202			if probePatch := convertAppProber(c.StartupProbe, startupz, statusPort); probePatch != nil {
   203				c.StartupProbe = probePatch
   204			}
   205			pod.Spec.Containers[i] = c
   206		}
   207	}
