   209	// kubeProbeToInternalProber converts a Kubernetes Probe to an Istio internal Prober
   210	func kubeProbeToInternalProber(probe *corev1.Probe) *Prober {
   211		if probe == nil {
   212			return nil
   213		}
   214	
   215		if probe.HTTPGet != nil {
   216			return &Prober{
   217				HTTPGet:        probe.HTTPGet,
   218				TimeoutSeconds: probe.TimeoutSeconds,
   219			}
   220		}
   221	
   222		if probe.TCPSocket != nil && features.RewriteTCPProbes {
   223			return &Prober{
   224				TCPSocket:      probe.TCPSocket,
   225				TimeoutSeconds: probe.TimeoutSeconds,
   226			}
   227		}
   228	
   229		return nil
   230	}
