		if p.HTTPGet != nil {
			probePort = &p.HTTPGet.Port
		} else if p.TCPSocket != nil {
			probePort = &p.TCPSocket.Port
		} else {
			// For gRPC, we use a simple int32 port, no need to resolve named ports
			return p
		}

