func (s *Server) handleAppProbeGRPC(w http.ResponseWriter, req *http.Request, prober *Prober, path string) {
	port := prober.GRPC.Port
	timeout := time.Duration(prober.TimeoutSeconds) * time.Second

	// Create a gRPC client connection to the application
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()

	conn, err := grpc.DialContext(ctx, fmt.Sprintf("%s:%d", s.appProbersDestination, port),
		grpc.WithTransportCredentials(insecure.NewCredentials()),
		grpc.WithBlock(),
	)
	if err != nil {
		log.Errorf("Failed to connect to gRPC service at %s:%d: %v", s.appProbersDestination, port, err)
		w.WriteHeader(http.StatusInternalServerError)
		return
	}
	defer conn.Close()

	// Create health check client
	client := healthpb.NewHealthClient(conn)

	// Perform health check
	// If Service is not specified, use empty string which is the default
	serviceName := ""
	if prober.GRPC.Service != nil {
		serviceName = *prober.GRPC.Service
	}

	resp, err := client.Check(ctx, &healthpb.HealthCheckRequest{
		Service: serviceName,
	})
	if err != nil {
		log.Errorf("gRPC health check failed for %s:%d service=%s: %v", s.appProbersDestination, port, serviceName, err)
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	// Check the health status
	if resp.GetStatus() == healthpb.HealthCheckResponse_SERVING {
		w.WriteHeader(http.StatusOK)
	} else {
		w.WriteHeader(http.StatusServiceUnavailable)
	}
