	fmt.Println("\n=== Test 2: Prober with GRPC field ===")
	proberJSON := `{
		"httpGet": {"path": "/health", "port": 8080},
		"tcpSocket": {"port": 9090},
		"grpc": {"port": 9090, "service": "my.service"},
		"timeoutSeconds": 5
	}`
